struct Hit { at: Int; value: Int; }
node parts: Rows<Float> { domain = 5; value = 1.0; }
node blank: Rows<Int> { domain = 100; value = 0; }
node density: kernel {
    requires { field.read; field.write; }
    input parts: Rows<Float> <- parts.result;
    input bins: Rows<Int> <- blank.result;
    domain = count(parts);
    output result: Rows<Int>;
    scatter into bins with sum {
        return Hit { at: element(), value: 1 };
    }
}
output result <- density.result;
